const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = ['자바스크립트 입문', '리액트 시작하기', 'CSS 레이아웃'];

const Search = () => {
  const [keyword, setKeyword] = useState('');
  const [count, setCount] = useState(courses.length);

  const handleChange = (event) => {
    const next = event.target.value;
    setKeyword(next);
    setCount(courses.filter((course) => course.includes(next)).length);
  };

  return (
    <div className="panel">
      <label className="field" htmlFor="q">코스 검색</label>
      <input className="field__input" id="q" type="search" value={keyword} onChange={handleChange} />
      <p className="count">코스 {count}개</p>
      <div className="row">
        <button className="clear" type="button" onClick={() => setKeyword('')}>지우기</button>
      </div>
    </div>
  );
};

root.render(<Search />);

